// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../../state.js";

/* Supervision duties — aSc prints these with `ttreports.printsubstduty`
 * ("Duty (Substitution)"). Chronexa had a supervision colour in the settings
 * and an on-screen supervision view, but nothing you could hand to a teacher.
 *
 * One A4 page: rows = periods, columns = days, each cell lists every room on
 * duty with its teacher. Reads `classroomsupervisions` (the aSc entity) and, as
 * a fallback, duty lessons that sit on the school's floor pseudo-classes.
 *
 * computeSupervisionGrid() is pure and exported so it can be tested and reused.
 */

function dayNames(school) {
  return (school.days && school.days.length)
    ? school.days.map((d) => d.short || d.name)
    : ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
}

/**
 * @returns {{days:string[], periods:number[], grid:Object<string, Array<{room:string,teacher:string}>>}}
 *   grid key is `${day}_${period}` (0-based day, 1-based period).
 */
export function computeSupervisionGrid(school) {
  const days = dayNames(school);
  const periods = (school.bell && school.bell.periods ? school.bell.periods : [])
    .filter((p) => p.isTeaching !== false)
    .map((p) => p.index);
  const periodList = periods.length ? periods : [1, 2, 3, 4, 5, 6, 7, 8];
  const roomById = new Map((school.classrooms || []).map((r) => [r.id, r.name || r.id]));
  const teacherById = new Map((school.teachers || []).map((t) => [t.id, t.name || t.short || t.id]));

  const grid = {};
  const push = (day, period, room, teacher) => {
    if (day == null || period == null) return;
    const key = `${day | 0}_${period | 0}`;
    (grid[key] = grid[key] || []).push({
      room: room || "",
      teacher: teacher || "",
    });
  };

  // 1. first-class supervision rows
  for (const s of school.classroomsupervisions || []) {
    push(s.day, s.period, roomById.get(s.classroomid) || "", teacherById.get(s.teacherid) || "");
  }

  // 2. fallback: duty lessons placed on floor pseudo-classes ("1st Floor" …)
  if (!Object.keys(grid).length) {
    const lessons = new Map((school.lessons || []).map((l) => [l.id, l]));
    const classById = new Map((school.classes || []).map((c) => [c.id, c]));
    const isDutyClass = (id) => /floor|duty|dozor|supervis/i.test((classById.get(id) || {}).name || "");
    for (const card of school.cards || []) {
      const l = lessons.get(card.lessonId);
      if (!l) continue;
      if (!(l.classIds || []).some(isDutyClass)) continue;
      push(card.day, card.period,
        roomById.get(card.classroomId) || "",
        (l.teacherIds || []).map((t) => teacherById.get(t) || t).join(", "));
    }
  }

  for (const key of Object.keys(grid)) {
    grid[key].sort((a, b) => a.room.localeCompare(b.room));
  }
  return { days, periods: periodList, grid };
}

(function () {
  "use strict";
  const U = window.APP.printTemplateUtils;
  if (!U) return;
  const { el, page, header, footer, emptyPage } = U;

  function render(school) {
    if (!school) return [emptyPage("No school")];
    const { days, periods, grid } = computeSupervisionGrid(school);
    const p = page(true);
    p.appendChild(header("Supervision duties",
      (school.schoolName || "") + "  ·  " + new Date().toLocaleDateString()));

    const tbl = el("table", { style: U.tableCSS() });
    const head = el("tr");
    head.appendChild(el("th", { style: U.thCSS() + ";width:26px" }, ""));
    days.forEach((d) => head.appendChild(el("th", { style: U.thCSS() }, d)));
    tbl.appendChild(el("thead", null, head));

    const tbody = el("tbody");
    periods.forEach((period) => {
      const tr = el("tr");
      tr.appendChild(el("td", { style: U.tdCSS() + ";font-weight:600;text-align:center" }, String(period)));
      days.forEach((_d, dayIdx) => {
        const cell = (grid[`${dayIdx}_${period}`] || []);
        const td = el("td", { style: U.tdCSS() + ";vertical-align:top;font-size:8.5px" },
          cell.length
            ? cell.map((c) => el("div", null, (c.room ? c.room + " — " : "") + c.teacher))
            : el("span", { style: "color:#bbb" }, "—"));
        tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
    tbl.appendChild(tbody);
    p.appendChild(tbl);

    const total = Object.values(grid).reduce((n, list) => n + list.length, 0);
    p.appendChild(el("div", { style: "margin-top:8px;font-size:9px;color:#666" },
      total ? `${total} duty slots` : "No supervision recorded for this file."));
    p.appendChild(footer());
    return [p];
  }

  window.APP.printTemplates.register("supervision_duties", {
    name: "Supervision duties",
    render,
  });
})();
